		public void TestGetInterpretedHTML_EmptyMessage()
		{
			var message = Factory.New<REXMessage>();
			var html = REXMessageInterpretationGenerator.GetInterpretedHTML(message);
			var body = @"<body><table border=""1"" cellpadding=""1"" cellspacing=""0"" width=""100%"" class=""table""><tr><td>&nbsp;</td></tr></table></body";
			AssertContains(body, html);
		}

